import type {PluginOptions} from '@docusaurus/plugin-content-docs';

/**
 * The School sidebar is autogenerated from `docs/school`, so that folder's
 * `_category_.json` is not applied on its own (category metadata is only read
 * for directories nested under the autogenerated root). Wrap the generated
 * items in that category and point the category at its index doc, which is
 * then left out of the child list.
 */
export const sidebarItemsGenerator: PluginOptions['sidebarItemsGenerator'] =
  async ({defaultSidebarItemsGenerator, ...args}) => {
  const items = await defaultSidebarItemsGenerator(args);
  if (args.item.dirName !== 'school') {
    return items;
  }

  const meta = args.categoriesMetadata.school;
  const link = meta?.link;
  if (!meta || !link || link.type !== 'doc') {
    return items;
  }

  return [
    {
      type: 'category',
      label: meta.label ?? 'School',
      collapsed: meta.collapsed ?? false,
      collapsible: meta.collapsible ?? true,
      link: {type: 'doc', id: link.id},
      items: items.filter(
        (item) => !(item.type === 'doc' && item.id === link.id),
      ),
    },
  ];
};
